<?php
require_once __DIR__ . '/functions.php';
requireUser();
$genreId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$genreStmt = $pdo->prepare('SELECT genre_id, genre_name, description FROM genres WHERE genre_id = :id'); $genreStmt->execute(['id' => $genreId]); $genre = $genreStmt->fetch();
if (!$genre) { http_response_code(404); exit('Genre not found.'); }
try {
	$stmt = $pdo->prepare(trackQuery() . ' JOIN track_genres tg ON tg.track_id = t.track_id WHERE tg.genre_id = :id ORDER BY ar.artist_name, al.title, t.track_number');
	$stmt->execute(['id' => $genreId]);
} catch (PDOException $exception) {
	$stmt = $pdo->prepare(
		'SELECT t.track_id, t.title, t.duration_seconds, t.track_number, t.audio_url, t.cover_image,
				t.lyrics, al.album_id, al.title AS album_title, al.cover_image AS album_cover,
				ar.artist_id, ar.artist_name
		 FROM tracks t
		 JOIN albums al ON al.album_id = t.album_id
		 JOIN artists ar ON ar.artist_id = al.artist_id
		 JOIN track_genres tg ON tg.track_id = t.track_id
		 WHERE tg.genre_id = :id
		 ORDER BY ar.artist_name, al.title, t.track_number'
	);
	$stmt->execute(['id' => $genreId]);
}
$tracks = $stmt->fetchAll();
