ing:0}.nav-arrow-btn:hover{background:rgba(255,255,255,0.14);cursor:pointer}.user-actions{display:flex;align-items:center;gap:16px;margin-left:auto}.premium-btn{background:#fff;color:#000;border:0;padding:9px 16px;border-radius:999px;font-weight:700;text-decoration:none}.user-menu-wrap{position:relative;display:flex;align-items:center}.user-icon-btn{width:38px;height:38px;border-radius:50%;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.06);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;padding:0}.user-icon-btn:hover{border-color:var(--spotify-green)}.account-menu{position:absolute;top:calc(100% + 12px);right:0;width:240px;background:rgba(18,18,18,0.98);border:1px solid rgba(255,255,255,0.12);border-radius:16px;box-shadow:0 18px 40px rgba(0,0,0,0.4);padding:16px;display:none;z-index:40}.account-menu.open{display:block}.account-menu .menu-header{display:flex;align-items:center;gap:12px;margin-bottom:12px;padding-bottom:12px;border-bottom:1px solid rgba(255,255,255,0.08)}.account-avatar{width:38px;height:38px;border-radius:50%;background:linear-gradient(135deg,#1ed760,#6ee7b7);color:#111;display:flex;align-items:center;justify-content:center;font-weight:800}.account-name{font-weight:700}.account-email{font-size:12px;color:var(--text-muted)}.account-details{display:grid;gap:8px;margin:12px 0}.account-row{display:flex;justify-content:space-between;gap:12px;font-size:13px;color:var(--text-muted)}.account-row strong{color:#fff}.logout-link{display:block;margin-top:8px;padding-top:12px;border-top:1px solid rgba(255,255,255,0.08);color:#ffb4b4;text-decoration:none}</style></head><body><header class="top-nav"><div class="nav-left"><a class="home-btn" href="user-dashbord.php"><i class="fas fa-house"></i> Home</a><div class="nav-arrows"><button type="button" class="nav-arrow-btn" aria-label="Go back" data-nav="back"><i class="fas fa-chevron-left"></i></button><button type="button" class="nav-arrow-btn" aria-label="Go forward" data-nav="forward"><i class="fas fa-chevron-right"></i></button></div></div><form class="top-search" action="search.php" method="get"><div class="search-shell"><i class="fas fa-search"></i><input type="text" name="q" placeholder="What do you want to play?" aria-label="Search songs, albums, artists"><button type="submit" aria-label="Search"><i class="fas fa-magnifying-glass"></i></button></div></form><div class="user-actions"><a class="premium-btn" href="subscriptions.php">Explore Premium</a><div class="user-menu-wrap"><button class="user-icon-btn" type="button" aria-label="Account information"><i class="fas fa-user"></i></button><div class="account-menu" aria-live="polite"><div class="menu-header"><div class="account-avatar"><?php echo strtoupper(substr(e($_SESSION['username'] ?? 'U'), 0, 1)); ?></div><div><div class="account-name"><?php echo e($_SESSION['username'] ?? 'User'); ?></div><div class="account-email"><?php echo e($_SESSION['email'] ?? 'No email found'); ?></div></div></div><div class="account-details"><div class="account-row"><span>Plan</span><strong><?php echo e($_SESSION['subscription_type'] ?? 'Free'); ?></strong></div><div class="account-row"><span>Country</span><strong><?php echo e($_SESSION['country'] ?? 'Not set'); ?></strong></div></div><a class="logout-link" href="../backend/logout.php">Log out</a></div></div></div></header><main class="main-content page"><p><a href="user-dashbord.php">Home</a></p><section class="panel"><h1><?php echo e($genre['genre_name']); ?></h1><p class="muted"><?php echo e($genre['description']); ?></p><?php foreach ($tracks as $track): ?><div class="row"><a href="track.php?id=<?php echo (int)$track['track_id']; ?>"><?php echo e($track['title']); ?></a> <span class="muted">- <?php echo e($track['artist_name']); ?> / <?php echo e($track['album_title']); ?></span></div><?php endforeach; ?><?php if (!$tracks): ?><p class="muted">No tracks in this genre yet.</p><?php endif; ?></section></main><script>document.querySelectorAll('.nav-arrow-btn').forEach(button => { button.addEventListener('click', () => { if (button.dataset.nav === 'back') { window.history.back(); } else { window.history.forward(); } }); }); const userIcon = document.querySelector('.user-icon-btn'); const accountMenu = document.querySelector('.account-menu'); if (userIcon && accountMenu) { userIcon.addEventListener('click', (event) => { event.stopPropagation(); accountMenu.classList.toggle('open'); }); document.addEventListener('click', (event) => { if (!accountMenu.contains(event.target) && !userIcon.contains(event.target)) { accountMenu.classList.remove('open'); } }); } </script></body></html>
